import math

# Categorize cluster cells by innermost 6
cluster_by_6 = {6: [], 17: [], 5: [], 3: [], 16: []}

for r, row in enumerate(grid):
    for c, val in enumerate(row):
        if val not in [1, 6]:
            # Find which 6 is closest
            min_dist = float('inf')
            closest_6 = None
            for sr, sc in [(2,1), (3,17), (5,5), (9,3), (9,16)]:
                d = math.sqrt((r - sr)**2 + (c - sc)**2)
                if d < min_dist:
                    min_dist = d
                    closest_6 = sc
            cluster_by_6[closest_6].append((r, c, val))

print("Cluster cells grouped by closest 6:")
for c6, cells in cluster_by_6.items():
    print(f"  6 at col {c6}: {cells}")

# Sum of values for each 6's group
print("\nSum of values:")
for c6, cells in cluster_by_6.items():
    total = sum(v for r, c, v in cells)
    print(f"  6 at col {c6}: sum = {total}, cells = {len(cells)}")

